<script setup lang="ts">
import AdminConsole from '../../components/console/AdminConsole.vue'
import ConsoleDrawer from '../../components/console/ConsoleDrawer.vue'
import ConsoleQueryButton from '../../components/console/ConsoleQueryButton.vue'
import ConsoleDiscardChangesDialog from '../../components/console/ConsoleDiscardChangesDialog.vue'
import ConsolePageHeading from '@orangezh1/qisvc-console-ui/components/ConsolePageHeading'
import ConsoleDataTable from '@orangezh1/qisvc-console-ui/components/ConsoleDataTable'
import ConsoleListFilters from '@orangezh1/qisvc-console-ui/components/ConsoleListFilters'
import ConsoleListSearch from '@orangezh1/qisvc-console-ui/components/ConsoleListSearch'
import ConsoleInput from '@orangezh1/qisvc-console-ui/components/ConsoleInput'
import ConsoleSettingsField from '@orangezh1/qisvc-console-ui/components/ConsoleSettingsField'
import ConsoleFormActions from '@orangezh1/qisvc-console-ui/components/ConsoleFormActions'
import ConsoleActionConfirmationDialog from '@orangezh1/qisvc-console-ui/components/ConsoleActionConfirmationDialog'
import {dateTime} from '../../utils/update-center'
definePageMeta({layout:'tenant',key:route=>route.path})
type Member={id:string;username:string;nickname:string;avatar:string|null;phone:string;roleId:string|null;role:{name:string;enabled:boolean};enabled:boolean;accountEnabled:boolean;allowMultipleSessions:boolean;version:number;accountVersion:number;createdAt:string;editable:boolean;accountEditable:boolean;owner:boolean}
type Listing={items:Member[];total:number;canWrite:boolean}
const auth=useApi('tenant'),tenantId=useTenantContext().tenantId.value,endpoint='/admin/tenants/'+encodeURIComponent(tenantId)+'/administrators',toast=useToast()
if(!auth.session.value?.permissions.includes('tenant:accounts.read'))throw createError({statusCode:403,statusMessage:'没有管理员访问权限'})
const q=ref(''),search=ref(''),status=ref('all'),appliedStatus=ref('all'),page=ref(1),pageSize=ref(20),loadAction=ref(''),mutation=ref(''),error=ref('')
const params=()=>new URLSearchParams({q:search.value,status:appliedStatus.value,page:String(page.value),pageSize:String(pageSize.value)})
const initial=await useAsyncData('tenant-administrators:'+auth.session.value.id+':'+tenantId,(_nuxt,{signal})=>auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal}))
const rows=ref<Listing>(initial.data.value??{items:[],total:0,canWrite:false});error.value=initial.error.value?.message||''
const columns=[{id:'staff',header:'管理员'},{accessorKey:'phone',header:'手机号'},{id:'role',header:'所属角色'},{id:'status',header:'状态'},{id:'created',header:'创建时间'},{id:'actions',header:'操作'}]
const mode=ref<'create'|'edit'|'password'>('create'),editing=ref<Member|null>(null),editorOpen=ref(false),formError=ref(''),requestId=ref(''),baseline=ref(''),showPassword=ref(false)
const form=reactive({username:'',nickname:'',phone:'',roleId:'',enabled:true,allowMultipleSessions:true,password:'',confirmPassword:''})
const dirty=computed(()=>editorOpen.value&&JSON.stringify(form)!==baseline.value),discard=useDiscardChanges(()=>!!mutation.value),canEditAccount=computed(()=>mode.value==='create'||!!editing.value?.accountEditable)
const roleSearch=ref(''),roleBusy=ref(false),roleError=ref(''),roleTotal=ref(0),roleOptions=ref<{label:string;value:string;disabled?:boolean}[]>([]),confirmOpen=ref(false),target=ref<Member|null>(null)
const lifetime=new AbortController();let disposed=false,sequence=0,roleSequence=0,controller:AbortController|undefined,roleController:AbortController|undefined
async function load(source='refresh'){controller?.abort();controller=new AbortController();const seq=++sequence;loadAction.value=source;try{const value=await auth.api<Listing>(endpoint+'?'+params(),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,controller.signal])});if(!disposed&&seq===sequence){rows.value=value;error.value=''}}catch(e:any){if(!disposed&&seq===sequence)error.value=e.message}finally{if(!disposed&&seq===sequence)loadAction.value=''}}
function guard(action:()=>void){if(mutation.value)return;if(dirty.value)discard.request(action);else action()}
function close(){editorOpen.value=false;form.password='';form.confirmPassword='';roleSequence++;roleController?.abort();roleBusy.value=false}
function refresh(){guard(()=>{close();void load('refresh')})}
function filter(source:'search'|'reset'){if(source==='reset'){q.value='';status.value='all'}search.value=q.value.trim();appliedStatus.value=status.value;page.value=1;void load(source)}
async function lookupRoles(){roleController?.abort();roleController=new AbortController();const seq=++roleSequence;roleBusy.value=true;roleError.value='';try{const value=await auth.api<{items:{id:string;name:string;assignable:boolean}[];total:number}>(endpoint+'/roles?'+new URLSearchParams({q:roleSearch.value,pageSize:'50'}),'GET',undefined,{signal:AbortSignal.any([lifetime.signal,roleController.signal])});if(disposed||seq!==roleSequence)return;roleOptions.value=value.items.map(row=>({label:row.name,value:row.id,disabled:!row.assignable}));roleTotal.value=value.total;if(editing.value?.roleId&&!roleOptions.value.some(row=>row.value===editing.value!.roleId))roleOptions.value.push({label:editing.value.role.name+(editing.value.role.enabled?'':'（已停用）'),value:editing.value.roleId,disabled:!editing.value.role.enabled})}catch(e:any){if(!disposed&&seq===roleSequence)roleError.value=e.message}finally{if(!disposed&&seq===roleSequence)roleBusy.value=false}}
watch(roleSearch,()=>{if(editorOpen.value&&mode.value!=='password')void lookupRoles()})
function open(type:typeof mode.value,row:Member|null=null){mode.value=type;editing.value=row;formError.value='';requestId.value=crypto.randomUUID();showPassword.value=false;Object.assign(form,{username:row?.username||'',nickname:row?.nickname||'',phone:row?.phone||'',roleId:row?.roleId||'',enabled:row?.enabled??true,allowMultipleSessions:row?.allowMultipleSessions??true,password:'',confirmPassword:''});baseline.value=JSON.stringify(form);roleSearch.value='';roleOptions.value=row?.roleId?[{label:row.role.name,value:row.roleId,disabled:!row.role.enabled}]:[];roleError.value='';editorOpen.value=true;if(type!=='password')void lookupRoles()}
async function save(){
 if(mutation.value||mode.value!=='password'&&(roleBusy.value||roleError.value))return;formError.value=''
 if(mode.value!=='edit'&&form.password!==form.confirmPassword){formError.value='两次输入的密码不一致';return}
 if(mode.value!=='password'&&!form.roleId){formError.value='请选择所属角色';return}
 mutation.value='save'
 try{const account={nickname:form.nickname,phone:form.phone,allowMultipleSessions:form.allowMultipleSessions},scope={roleId:form.roleId,enabled:form.enabled},row=editing.value
  if(mode.value==='create')await auth.api(endpoint,'POST',{...account,...scope,username:form.username,password:form.password,requestId:requestId.value},{signal:lifetime.signal})
  else if(row)await auth.api(endpoint+'/'+row.id+(mode.value==='password'?'/password':''),'PUT',{version:row.version,accountVersion:row.accountVersion,...(mode.value==='password'?{password:form.password}:{...scope,...(row.accountEditable?account:{})})},{signal:lifetime.signal})
  if(!disposed){close();toast.add({title:mode.value==='create'?'管理员已创建':mode.value==='password'?'密码已重置，原有登录已失效':'管理员已更新，原有登录已失效',color:'success'});await load('mutation')}
 }catch(e:any){if(!disposed)formError.value=e.message}finally{if(!disposed)mutation.value=''}
}
async function remove(){const row=target.value;if(!row||mutation.value)return;mutation.value='remove';try{await auth.api(endpoint+'/'+row.id,'DELETE',{version:row.version},{signal:lifetime.signal});if(!disposed){confirmOpen.value=false;toast.add({title:'已移除管理员授权',color:'success'});await load('mutation')}}catch(e:any){if(!disposed)toast.add({title:e.message,color:'error'})}finally{if(!disposed)mutation.value=''}}
onBeforeRouteLeave(to=>{if(mutation.value)return false;if(dirty.value){discard.request(()=>{close();void navigateTo(to.fullPath)});return false}})
function beforeUnload(event:BeforeUnloadEvent){if(dirty.value||mutation.value){event.preventDefault();event.returnValue=''}}
onMounted(()=>window.addEventListener('beforeunload',beforeUnload));onBeforeUnmount(()=>{disposed=true;sequence++;roleSequence++;controller?.abort();roleController?.abort();lifetime.abort();if(import.meta.client)window.removeEventListener('beforeunload',beforeUnload)})
</script>
<template><AdminConsole :refreshing="loadAction==='refresh'" @refresh="refresh"><div class="space-y-5">
 <ConsolePageHeading title="管理员"><template #actions><UButton v-if="rows.canWrite" icon="i-lucide-user-plus" :disabled="!!error||!!mutation" @click="open('create')">新增管理员</UButton></template></ConsolePageHeading>
 <form @submit.prevent="filter('search')"><ConsoleListFilters><ConsoleListSearch v-model="q" placeholder="搜索账号、名称或手机号"/><USelect v-model="status" :items="[{label:'全部状态',value:'all'},{label:'启用',value:'enabled'},{label:'停用',value:'disabled'}]" aria-label="管理员状态筛选"/><div class="flex shrink-0 items-center gap-3"><ConsoleQueryButton type="submit" :loading="loadAction==='search'">查询</ConsoleQueryButton><ConsoleQueryButton kind="reset" color="neutral" variant="outline" :loading="loadAction==='reset'" @click="filter('reset')">重置</ConsoleQueryButton></div></ConsoleListFilters></form>
 <ConsoleDataTable :data="rows.items" :columns="columns" :error="error" :page="page" :page-size="pageSize" :total="rows.total" :client-pagination="false" empty-title="暂无管理员" empty-description="先创建角色，再添加管理员。" @retry="load('retry')" @update:page="page=$event;load('page')" @update:page-size="pageSize=$event;page=1;load('page')">
  <template #staff-cell="{row}"><div class="flex items-center gap-3"><img :src="row.original.avatar||'/brand/admin-avatar.png'" alt="" class="size-9 shrink-0 rounded-full object-cover"/><div><div class="flex items-center gap-2"><span class="font-medium text-highlighted">{{row.original.nickname}}</span><UBadge v-if="row.original.owner" size="sm" color="neutral" variant="subtle">负责人</UBadge><UBadge v-if="row.original.id===auth.session.value?.id" size="sm" variant="subtle">本人</UBadge></div><p class="mt-1 text-xs text-muted">{{row.original.username}}</p></div></div></template>
  <template #phone-cell="{row}">{{row.original.phone||'—'}}</template><template #role-cell="{row}">{{row.original.role.name}}<span v-if="!row.original.role.enabled" class="ml-1 text-xs text-warning">角色已停用</span></template>
  <template #status-cell="{row}"><UBadge :color="row.original.enabled&&row.original.accountEnabled?'success':'neutral'" variant="subtle">{{!row.original.accountEnabled?'账号已停用':row.original.enabled?'启用':'停用'}}</UBadge></template><template #created-cell="{row}"><span class="text-xs text-muted">{{dateTime(row.original.createdAt)}}</span></template>
  <template #actions-cell="{row}"><div v-if="row.original.id===auth.session.value?.id" class="flex gap-3"><UButton class="px-0" size="sm" variant="link" to="/admin/profile">编辑</UButton><UButton class="px-0" size="sm" variant="link" to="/admin/profile#password">修改密码</UButton></div><div v-else-if="row.original.editable" class="flex gap-3"><UButton class="px-0" size="sm" variant="link" @click="open('edit',row.original)">编辑</UButton><UButton v-if="row.original.accountEditable" class="px-0" size="sm" variant="link" @click="open('password',row.original)">重置密码</UButton><UButton class="px-0" size="sm" variant="link" color="error" @click="target=row.original;confirmOpen=true">移除</UButton></div><span v-else class="text-xs text-muted">{{row.original.owner?'负责人受保护':row.original.id===auth.session.value?.id?'当前账号':'只读'}}</span></template>
 </ConsoleDataTable>
 <ConsoleDrawer :open="editorOpen" :title="mode==='create'?'新增管理员':mode==='password'?'重置密码':'编辑管理员'" :dismissible="!mutation" :close="!mutation" @update:open="!$event&&guard(close)"><template #body><form id="tenant-administrator-form" novalidate class="space-y-6" @submit.prevent="save">
  <ConsoleSettingsField label="登录账号" required><ConsoleInput v-model="form.username" aria-label="登录账号" :disabled="!!mutation||mode!=='create'" autocomplete="off" required pattern="[a-zA-Z0-9][a-zA-Z0-9_.-]{2,31}" :maxlength="32" placeholder="3–32 位字母、数字、点、横线或下划线"/></ConsoleSettingsField>
  <template v-if="mode!=='password'"><ConsoleSettingsField label="名称" required><ConsoleInput v-model="form.nickname" aria-label="名称" required :maxlength="32" :disabled="!!mutation||!canEditAccount"/></ConsoleSettingsField><ConsoleSettingsField label="手机号"><ConsoleInput v-model="form.phone" aria-label="手机号" type="tel" :maxlength="32" :disabled="!!mutation||!canEditAccount"/></ConsoleSettingsField>
   <ConsoleSettingsField label="所属角色" required><USelectMenu v-model="form.roleId" v-model:search-term="roleSearch" :items="roleOptions" value-key="value" ignore-filter :loading="roleBusy" :disabled="!!mutation" class="w-full" placeholder="搜索并选择角色" aria-label="所属角色"/><p v-if="!roleBusy&&!roleError&&!roleOptions.length" class="mt-2 text-xs text-muted">暂无可分配角色，请先创建并启用角色。</p><p v-if="roleTotal>50" class="mt-2 text-xs text-muted">匹配 {{roleTotal}} 个角色，请搜索名称缩小范围。</p></ConsoleSettingsField>
   <UAlert v-if="roleError" color="error" :title="roleError"><template #actions><UButton size="sm" variant="outline" color="neutral" @click="lookupRoles">重试</UButton></template></UAlert>
  </template>
  <template v-if="mode!=='edit'"><ConsoleSettingsField :label="mode==='create'?'初始密码':'新密码'" required><ConsoleInput v-model="form.password" aria-label="密码" :type="showPassword?'text':'password'" autocomplete="new-password" required :minlength="6" :maxlength="128" :disabled="!!mutation"><template #trailing><UButton type="button" color="neutral" variant="ghost" size="xs" :icon="showPassword?'i-lucide-eye-off':'i-lucide-eye'" :aria-label="showPassword?'隐藏密码':'显示密码'" @click="showPassword=!showPassword"/></template></ConsoleInput></ConsoleSettingsField><ConsoleSettingsField label="确认密码" required><ConsoleInput v-model="form.confirmPassword" aria-label="确认密码" type="password" autocomplete="new-password" required :disabled="!!mutation"/></ConsoleSettingsField></template>
  <template v-if="mode!=='password'"><ConsoleSettingsField v-if="canEditAccount" label="多处登录"><USwitch v-model="form.allowMultipleSessions" label="允许多处同时登录" :disabled="!!mutation"/></ConsoleSettingsField><ConsoleSettingsField label="账号状态"><USwitch v-model="form.enabled" label="启用管理员" :disabled="!!mutation"/></ConsoleSettingsField></template>
  <p v-if="mode==='edit'&&!canEditAccount" class="text-xs text-muted">当前可调整该账号的角色与状态，个人资料和密码可由本人修改。</p><p v-if="mode!=='create'" class="text-xs text-muted">保存后，该账号的原有登录会话将失效。</p><UAlert v-if="formError" color="error" :title="formError"/>
 </form></template><template #footer><ConsoleFormActions class="w-full"><UButton color="neutral" variant="outline" :disabled="!!mutation" @click="guard(close)">取消</UButton><UButton type="submit" form="tenant-administrator-form" :loading="mutation==='save'" :disabled="mode!=='password'&&(roleBusy||!!roleError||!form.roleId)">{{mode==='create'?'创建管理员':mode==='password'?'确认重置':'保存修改'}}</UButton></ConsoleFormActions></template></ConsoleDrawer>
 <ConsoleActionConfirmationDialog v-model:open="confirmOpen" title="移除管理员？" :subject="target?.nickname" description="移除该管理员的后台访问权限，同时撤销原有登录；操作历史会保留。" confirm-label="移除" color="error" :loading="mutation==='remove'" @confirm="remove"/><ConsoleDiscardChangesDialog :controller="discard"/>
</div></AdminConsole></template>
